INSERT INTO prompts (id, school_id, text, word_limit, sort_order)
VALUES
  ('purdue--how-will-opportunities-at-purdue-support', 'purdue', 'How will opportunities at Purdue support your interests, both in and out of the classroom? (Respond in 250 words or fewer.)', 250, 0),
  ('purdue--briefly-discuss-your-reasons-for-choosing', 'purdue', 'Briefly discuss your reasons for choosing your major and your interest in studying at this campus location (Indianapolis or West Lafayette). (Respond in 250 words or fewer.)', 250, 1),
  ('georgia-tech--why-do-you-want-to-study', 'georgia-tech', 'Why do you want to study your chosen major and why do you want to study your major at Georgia Tech?*(300 words)', 300, 0),
  ('tufts--please-complete-the-following-statement-i', 'tufts', 'Please complete the following statement: "I am applying to Tufts because..." (150-250 words)', 250, 0),
  ('tufts--it-s-cool-to-love-learning', 'tufts', 'It’s cool to love learning. What excites your intellectual curiosity, and why?(200-250words)', 250, 1),
  ('north-western--we-want-to-be-sure-we', 'north-western', 'We want to be sure we’re considering your application in the context of your personal experiences: What aspects of your background (your identity, your school setting, your community, your household, etc.) have most shaped how you see yourself engaging in Northwestern’s community, be it academically, extracurricularly, culturally, politically, socially, or otherwise? (fewer than 300 words)', 300, 0),
  ('north-western--2-northwestern-fosters-a-distinctively-interdisciplinary', 'north-western', '2)  Northwestern fosters a distinctively interdisciplinary culture. We believe discovery and innovation thrive at the intersection of diverse ideas, perspectives, and academic interests. Within this setting, if you could dream up an undergraduate class, research project, or creative effort (a start-up, a design prototype, a performance, etc.), what would it be? Who might be some ideal classmates or collaborators?(200 words)', 200, 1),
  ('north-western--5-northwestern-is-a-place-where', 'north-western', '5)  Northwestern is a place where people with diverse backgrounds from all over the world can study, live, and talk with one another. This range of experiences and viewpoints immeasurably enriches learning. How might your individual background contribute to this diversity of perspectives in Northwestern’s classrooms and around our campus?(200 words)', 200, 2),
  ('caltech--why-did-you-choose-your-proposed', 'caltech', 'Why did you choose your proposed area of interest? If you selected ‘other’, what topics are you interested in pursuing?*(200 words)', 200, 0),
  ('caltech--regardless-of-your-stem-interest-listed', 'caltech', 'Regardless of your STEM interest listed above, take this opportunity to nerd out and talk to us about whatever STEM rabbit hole you have found yourself falling into. Be as specific or broad as you would like.*(150 words)', 150, 1),
  ('caltech--tell-us-about-a-meaningful-stem', 'caltech', 'Tell us about a meaningful STEM-related experience from the last few years and share how and why it inspired your curiosity.(200 words)', 200, 2),
  ('caltech--the-creativity-inventiveness-and-innovation-of', 'caltech', 'The creativity, inventiveness, and innovation of Caltech''s students, faculty, and researchers have won Nobel Prizes and put rovers on Mars. But Techers also imagine smaller-scale innovations every day, from new ways to design solar cells to how to 3D-print dorm decor to experimenting in the kitchen. How have you been a creator, inventor, or innovator in your own life?*(200 words)', 200, 3),
  ('caltech--each-if-you-could-teach-a', 'caltech', 'each: If you could teach a class on any topic or concept, what would it be and why? (125 words)
Hobby: What is an interest or hobby you do for fun, and why does it bring you joy?(125 words)', 125, 4),
  ('john--over-the-past-150-years-every', 'john', 'Over the past 150 years, every monumental discovery at Hopkins has started with a first step: The first draft by a Pulitzer Prize-winning author. A prototype that led to a life-changing medical invention. The first pitch that launched a new startup venture. As we commemorate the university''s sesquicentennial—150 years since its founding—we continue to celebrate first steps just as much as final achievements. Tell us about an important first in your life—big or small—that has shaped you. (350 word limit)', 350, 0),
  ('usc--describe-how-you-plan-to-pursue', 'usc', 'Describe how you plan to pursue your academic interests and why you want to explore them at USC specifically. Please feel free to address your first- and second-choice major selections. (Approximately 250 words)', 250, 0),
  ('usc--describe-yourself-in-three-words-first', 'usc', 'Describe yourself in three words. First Word:*Second Word:*Third Word:*What is your favorite snack?*Best movie of all time:*Dream job:*If your life had a theme song, what would it be?*Dream trip:*What TV show will you binge watch next? *Which well-known person or fictional character would be your ideal roommate?*Favorite book:*If you could teach a class on any topic, what would it be?', NULL, 1),
  ('cornell--define-community-in-the-way-that', 'cornell', 'Define community in the way that is most meaningful to you. This community example can be drawn from your family, school, workplace, activities or interests, or any other group you belong to.*(350 words)', 350, 0),
  ('cmu--most-students-choose-their-intended-major', 'cmu', 'Most students choose their intended major or area of study based on a passion or inspiration that’s developed over time – what passion or inspiration led you to choose this area of study?
(300 word maximum)', 300, 0),
  ('cmu--many-students-pursue-college-for-a', 'cmu', 'Many students pursue college for a specific degree, career opportunity or personal goal. Whichever it may be, learning will be critical to achieve your ultimate goal. As you think ahead to the process of learning during your college years, how will you define a successful college experience?
(300 word maximum)', 300, 1),
  ('cmu--consider-your-application-as-a-whole', 'cmu', 'Consider your application as a whole. What do you personally want to emphasize about your application for the admission committee’s consideration? Highlight something that’s important to you or something you haven’t had a chance to share. Tell us, don’t show us (no websites please).
(300 word maximum)', 300, 2),
  ('boston-university--1-reflect-on-a-social-or', 'boston-university', '1. Reflect on a social or community issue that deeply resonates with you. Why is it important to you, and how have you been involved in addressing or raising awareness about it?(300 words)', 300, 0),
  ('boston-university--or-2-what-about-being-a', 'boston-university', 'OR
2. What about being a student at BU most excites you? How do you hope to contribute to our campus community?*(300 words)', 300, 1),
  ('upenn--write-a-short-thank-you-note', 'upenn', 'Write a short thank-you note to someone you have not yet thanked and would like to acknowledge. (We encourage you to share this note with that person, if possible, and reflect on the experience!) (150-200 words)', 200, 0),
  ('upenn--how-will-you-explore-community-at', 'upenn', 'How will you explore community at Penn? Consider how Penn will help shape your perspective, and how your experiences and perspective will help shape Penn. (150-200 words)', 200, 1),
  ('upenn--penn-engineering-prepares-its-students-to', 'upenn', 'Penn Engineering prepares its students to become leaders in technology by combining a strong foundation in the natural sciences and mathematics with depth of study in focused disciplinary majors. Please share how you plan to pursue your engineering interests at Penn, particularly within the intended major you selected. (150-200 words)', 200, 2),
  ('brown--browns-open-curriculum-allows-students-to', 'brown', 'Brown''s Open Curriculum allows students to explore broadly while also diving deeply into their academic pursuits. Tell us about any academic interests that excite you, and how you might pursue them at Brown. (250 word limit)', 250, 0),
  ('brown--students-entering-brown-often-find-that', 'brown', 'Students entering Brown often find that making their home on College Hill naturally invites reflection on where they came from. Share how an aspect of your growing up has inspired or challenged you, and what unique contributions this might allow you to make to the Brown community. (250 word limit)', 250, 1),
  ('brown--brown-students-care-deeply-about-their', 'brown', 'Brown students care deeply about their work and the world around them. Students find contentment, satisfaction, and meaning in daily interactions and major discoveries. Whether big or small, mundane or spectacular, tell us about something that brings you joy. (250 word limit)', 250, 2),
  ('brown--what-three-words-best-describe-you', 'brown', 'What three words best describe you? (3 word limit)', 3, 3),
  ('brown--if-you-could-teach-a-class', 'brown', 'If you could teach a class on any one thing, whether academic or otherwise, what would it be? (100 word limit)', 100, 4),
  ('brown--in-one-sentence-why-brown-50', 'brown', 'In one sentence, why Brown? (50 word limit)', 50, 5),
  ('yale--reflect-on-how-your-interests-values', 'yale', 'Reflect on how your interests, values, and/or experiences have drawn you to Yale (125 words or fewer)', 125, 0),
  ('yale--what-inspires-you', 'yale', 'What inspires you?', NULL, 1),
  ('yale--if-you-could-teach-any-college', 'yale', 'If you could teach any college course, write a book, or create an original piece of art of any kind, what would it be?', NULL, 2),
  ('yale--other-than-a-family-member-who', 'yale', 'Other than a family member, who is someone who has had a significant influence on you? What has been the impact of their influence?', NULL, 3),
  ('yale--what-is-something-about-you-that', 'yale', 'What is something about you that is not included anywhere else in your application?', NULL, 4),
  ('yale--3-reflect-on-an-element-of', 'yale', '3. Reflect on an element of your personal experience that you feel will enrich your college. How has it shaped you?', NULL, 5),
  ('mit--tell-us-more-about-why-this', 'mit', 'Tell us more about why this field of study at MIT appeals to you. (100 words)', 100, 0),
  ('mit--we-know-you-lead-a-busy', 'mit', 'We know you lead a busy life, full of activities, many of which are required of you. Tell us about something you do simply for the pleasure of it. (150 words)', 150, 1),
  ('mit--while-some-reach-their-goals-following', 'mit', 'While some reach their goals following well-trodden paths, others blaze their own trails achieving the unexpected. In what ways have you done something different than what was expected in your educational journey? (225 words)', 225, 2),
  ('mit--mit-brings-people-with-diverse-backgrounds', 'mit', 'MIT brings people with diverse backgrounds together to collaborate, from tackling the world’s biggest challenges to lending a helping hand. Describe one way you have collaborated with others to learn from them, with them, or contribute to your community together. (225 words)', 225, 3),
  ('mit--how-did-you-manage-a-situation', 'mit', 'How did you manage a situation or challenge that you didn’t expect? What did you learn from it? (225 words)', 225, 4),
  ('mit--no-application-can-meet-the-needs', 'mit', 'No application can meet the needs of every individual. If there is significant information that you were not able to include elsewhere in the application, you may include it here. (Many students will leave this section blank—and that’s okay.) (300 words)', 300, 5),
  ('harvard--harvard-has-long-recognized-the-importance', 'harvard', 'Harvard has long recognized the importance of enrolling a student body with a diversity of perspectives and experiences. How will the life experiences that shaped who you are today enable you to contribute to Harvard?', NULL, 0),
  ('harvard--describe-a-time-when-you-strongly', 'harvard', 'Describe a time when you strongly disagreed with someone about an idea or issue. How did you communicate or engage with this person? What did you learn from this experience?', NULL, 1),
  ('harvard--briefly-describe-any-of-your-extracurricular', 'harvard', 'Briefly describe any of your extracurricular activities, employment experience, travel, or family responsibilities that have shaped who you are.', NULL, 2),
  ('harvard--how-do-you-hope-to-use', 'harvard', 'How do you hope to use your Harvard education in the future?', NULL, 3),
  ('harvard--top-3-things-your-roommates-might', 'harvard', 'Top 3 things your roommates might like to know about you.', NULL, 4),
  ('columbia--list-a-selection-of-texts-resources', 'columbia', 'List a selection of texts, resources and outlets that have contributed to your intellectual development outside of academic courses, including but not limited to books, journals, websites, podcasts, essays, plays, presentations, videos, museums and other content that you enjoy. (100 words or fewer)', 100, 0),
  ('columbia--tell-us-about-an-aspect-of', 'columbia', 'Tell us about an aspect of your life so far or your lived experience that is important to you, and describe how it has shaped the way you would learn from and contribute to Columbia''s multidimensional and collaborative environment. (150 words or fewer)', 150, 1),
  ('columbia--at-columbia-students-representing-a-wide', 'columbia', 'At Columbia, students representing a wide range of perspectives are invited to live and learn together. In such a community, questions and debates naturally arise. Please describe a time when you did not agree with someone and discuss how you engaged with them and what you took away from the interaction. (150 words or fewer)', 150, 2),
  ('columbia--in-college-university-students-are-often', 'columbia', 'In college/university, students are often challenged in ways that they could not anticipate. Please describe a situation in which you have navigated through adversity and discuss how you changed as a result. (150 words or fewer)', 150, 3),
  ('columbia--why-are-you-interested-in-attending', 'columbia', 'Why are you interested in attending Columbia University? We encourage you to consider the aspect(s) that you find unique and compelling about Columbia. (150 words or fewer)', 150, 4),
  ('columbia--course-specific-question', 'columbia', 'course specific question', NULL, 5),
  ('princeton--princeton-values-community-and-encourages-students', 'princeton', 'Princeton values community and encourages students, faculty, staff and leadership to engage in respectful conversations that can expand their perspectives and challenge their ideas and beliefs. As a prospective member of this community, reflect on how your lived experiences will impact the conversations you will have in the classroom, the dining hall or other campus spaces. What lessons have you learned in life thus far? What will your classmates learn from you? In short, how has your lived experience shaped you? (500 words or fewer)', 500, 0),
  ('princeton--princeton-has-a-longstanding-commitment-to', 'princeton', 'Princeton has a longstanding commitment to understanding our responsibility to society through service and civic engagement. How does your own story intersect with these ideals? (250 words or fewer)', 250, 1),
  ('princeton--what-is-a-new-skill-you', 'princeton', 'What is a new skill you would like to learn in college?', NULL, 2),
  ('princeton--what-brings-you-joy', 'princeton', 'What brings you joy?', NULL, 3),
  ('princeton--what-song-represents-the-soundtrack-of', 'princeton', 'What song represents the soundtrack of your life at this moment?', NULL, 4),
  ('princeton--submit-a-paper', 'princeton', 'Submit a paper', NULL, 5),
  ('stanford--most-significant-challenge-society-faces', 'stanford', 'Most significant challenge society faces', NULL, 0),
  ('stanford--what-did-you-do-the-last', 'stanford', 'What did you do the last 2 summers', NULL, 1),
  ('stanford--historical-moment-or-event-youd-like', 'stanford', 'Historical moment or event you''d like to witness', NULL, 2),
  ('stanford--elaborate-on-extracurricular-activity-job-or', 'stanford', 'Elaborate on Extracurricular activity, job, or family responsibility', NULL, 3),
  ('stanford--five-things-that-are-important-to', 'stanford', 'Five things that are important to you', NULL, 4),
  ('stanford--idea-or-experience-that-makes-you', 'stanford', 'Idea or experience that makes you excited about learning', NULL, 5),
  ('stanford--note-to-future-roommate', 'stanford', 'Note to future roommate', NULL, 6),
